// frontend/src/pages/Menu.js

import React, { useEffect, useState } from "react";
import api from "../services/api";

export default function Menu({ onAddToCart }) {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    api
      .get("/products")
      .then((res) => setProducts(res.data))
      .catch((err) => console.error("Eroare la încărcare produse:", err));
  }, []);

  // 1) Grupează produsele după categorie într-un obiect de forma { [category]: [arrayProduse] }
  const groupedByCategory = products.reduce((acc, product) => {
    const cat = product.Category || "Altele";
    if (!acc[cat]) {
      acc[cat] = [];
    }
    acc[cat].push(product);
    return acc;
  }, {});

  // 2) Definește ordinea fixă (opțional) a categoriilor, ca să nu apară haotic.
  const categoryOrder = [
    "Pizza",
    "Burger",
    "Salad",
    "Ciorba",
    "Paste",
    "Traditional",
    "Desert",
    "Racoritoare",
  ];

  // 3) Creează un array cu numele tuturor categoriilor, în ordinea dorită:
  //    - Mai întâi cele din categoryOrder care există efectiv în groupedByCategory
  //    - Apoi restul categoriilor (cele care nu sunt în categoryOrder), sortate alfabetic
  const allCategories = [
    ...categoryOrder.filter((c) => groupedByCategory[c]),
    ...Object.keys(groupedByCategory)
      .filter((c) => !categoryOrder.includes(c))
      .sort(),
  ];

  return (
    <div style={{ padding: "0 20px", marginBottom: 40 }}>
      {/* ──────────────────── Titlu general ──────────────────── */}
      <h2 style={{ textAlign: "center", margin: "20px 0" }}>Meniu</h2>

      {/* ──────────────────── Mini‐meniu intern (Tab‐uri) ──────────────────── */}
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          flexWrap: "wrap",
          gap: "10px",
          marginBottom: "30px",
        }}
      >
        {allCategories.map((category) => (
          <a
            key={category}
            href={`#${category}`}
            style={{
              padding: "8px 16px",
              backgroundColor: "#ffcc00",
              color: "#000",
              borderRadius: 4,
              textDecoration: "none",
              fontWeight: "bold",
            }}
          >
            {category}
          </a>
        ))}
      </div>

      {/* ──────────────────── Secțiuni pe categorii ──────────────────── */}
      {allCategories.map((category) => (
        <div key={category} style={{ marginBottom: "50px" }}>
          {/* Titlul categoriei cu id */}
          <h3
            id={category} 
            style={{
              textAlign: "left",
              margin: "40px 0 20px",
              paddingLeft: "10px",
              fontSize: "1.5em",
              borderBottom: "2px solid #ddd",
              paddingBottom: "8px",
            }}
          >
            {category}
          </h3>

          {/* Container-ul produselor din acea categorie */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              gap: "20px",
            }}
          >
            {groupedByCategory[category].map((p) => (
              <div
                key={p.ProductId}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: 4,
                  padding: "10px",
                  width: "200px",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between",
                  backgroundColor: "#fff",
                  boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
                }}
              >
                {/* Imaginea produsului (preluată direct din ImageUrl) */}
                {p.ImageUrl ? (
                  <img
                    src={p.ImageUrl}
                    alt={p.Name}
                    style={{
                      width: "100%",
                      height: 120,
                      objectFit: "cover",
                      borderRadius: 4,
                      marginBottom: 8,
                    }}
                  />
                ) : (
                  <div
                    style={{
                      width: "100%",
                      height: 120,
                      backgroundColor: "#f0f0f0",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      color: "#888",
                      marginBottom: 8,
                    }}
                  >
                    (fără poză)
                  </div>
                )}

                {/* Numele, descrierea și prețul produsului */}
                <div style={{ flexGrow: 1 }}>
                  <h4
                    style={{
                      margin: "0 0 8px",
                      textAlign: "center",
                      fontSize: "1.1em",
                    }}
                  >
                    {p.Name}
                  </h4>
                  <p style={{ margin: "0 0 8px", fontSize: "0.9em" }}>
                    {p.Description}
                  </p>
                  <p style={{ margin: "0 0 12px", fontWeight: "bold" }}>
                    {p.Price} lei
                  </p>
                </div>

                {/* Butonul "Adaugă în coș" */}
                <button
                  onClick={() =>
                    onAddToCart({
                      productId:    p.ProductId,
                      name:         p.Name,
                      description:  p.Description,
                      imageUrl:     p.ImageUrl,
                      quantity:     1,
                      pricePerUnit: p.Price,
                    })
                  }
                  disabled={!p.IsAvailable}
                  style={{
                    padding: "8px",
                    borderRadius: 4,
                    cursor: p.IsAvailable ? "pointer" : "not-allowed",
                    backgroundColor: p.IsAvailable ? "#ffcc00" : "#ccc",
                    color: "#000",
                    border: "none",
                    marginTop: 8,
                    fontWeight: "bold",
                  }}
                >
                  {p.IsAvailable ? "Adaugă în coș" : "Indisponibil"}
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
